    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-2: #eef3ff;
        --text: #102033;
        --muted: #5b6b82;
        --border: #d6deea;
        --accent: #4f46e5;
        --accent-strong: #4338ca;
        --focus: #1d4ed8;
        --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(79, 70, 229, 0.12), transparent 36%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      }

      a.skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-160%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        text-decoration: none;
        box-shadow: var(--shadow);
      }

      a.skip-link:focus {
        transform: translateY(0);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 5rem 1.25rem 2rem;
      }

      .card {
        width: min(100%, 42rem);
        background: var(--surface);
        border: 1px solid rgba(214, 222, 234, 0.9);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 2.25rem);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: var(--surface-2);
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 600;
      }

      h1 {
        margin: 1rem 0 0.5rem;
        font-size: clamp(1.8rem, 4vw, 2.5rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 1.75rem;
        color: var(--muted);
        max-width: 38rem;
      }

      form {
        margin: 0;
      }

      .form-field {
        margin: 0;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        padding: 0;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .required {
        color: #b91c1c;
      }

      .help-text {
        margin: 0.5rem 0 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .options {
        display: grid;
        gap: 0.75rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.875rem;
        padding: 1rem 1rem 1rem 0.95rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #fbfcff;
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background-color 160ms ease,
          transform 160ms ease;
      }

      .option:hover {
        border-color: #c0cae0;
        background: #f8faff;
      }

      .option:has(input:focus-visible) {
        outline: 3px solid color-mix(in srgb, var(--focus) 22%, transparent);
        outline-offset: 2px;
      }

      .option:has(input:checked) {
        border-color: rgba(79, 70, 229, 0.5);
        background: rgba(79, 70, 229, 0.06);
      }

      input[type="radio"] {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .option-text {
        display: grid;
        gap: 0.15rem;
      }

      .option-title {
        font-weight: 600;
      }

      .option-copy {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      button[type="submit"] {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        box-shadow: 0 12px 24px rgba(79, 70, 229, 0.22);
        cursor: pointer;
      }

      button[type="submit"]:hover {
        filter: brightness(1.02);
      }

      button[type="submit"]:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.25rem;
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 30rem) {
        main {
          padding-inline: 0.75rem;
        }

        .card {
          border-radius: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button[type="submit"] {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
          scroll-behavior: auto !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .option,
        button[type="submit"] {
          forced-color-adjust: auto;
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .eyebrow {
          border: 1px solid CanvasText;
        }

        .option:has(input:focus-visible),
        button[type="submit"]:focus-visible,
        a.skip-link:focus {
          outline: 2px solid Highlight;
          outline-offset: 2px;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <main id="maincontent" tabindex="-1">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Notification settings</h1>
        <p class="intro">Choose the channel you want us to use when we send you updates.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
              <p class="help-text" id="notification-help">Pick one option. You can change this later.</p>

              <div class="options">
                <label class="option" for="notification-email">
                  <input id="notification-email" name="notification-preference" type="radio" value="email" required />
                  <span class="option-text">
                    <span class="option-title">Email</span>
                    <span class="option-copy">Best for longer updates and summaries.</span>
                  </span>
                </label>

                <label class="option" for="notification-sms">
                  <input id="notification-sms" name="notification-preference" type="radio" value="sms" required />
                  <span class="option-text">
                    <span class="option-title">SMS</span>
                    <span class="option-copy">Useful for time-sensitive alerts.</span>
                  </span>
                </label>

                <label class="option" for="notification-push">
                  <input id="notification-push" name="notification-preference" type="radio" value="push" required />
                  <span class="option-text">
                    <span class="option-title">Push Notifications</span>
                    <span class="option-copy">Great for instant updates in the app.</span>
                  </span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Save preferences</button>
          </div>

          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = form.querySelector('input[name="notification-preference"]:checked');
        if (!selected) {
          status.textContent = "Error: Choose one notification method before saving.";
          return;
        }

        status.textContent = `Saved: ${selected.nextElementSibling.querySelector(".option-title").textContent}.`;
      });
    </script>
  </body>
</html>
