      .option-text {
        display: grid;
        gap: 0.15rem;
      }

      .option-title {
        font-weight: 600;
      }

      .option-copy {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        margin-top: 1.5rem;
      }

      button[type="submit"] {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        box-shadow: 0 12px 24px rgba(79, 70, 229, 0.22);
