      button[type="submit"]:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.25rem;
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (max-width: 30rem) {
        main {
          padding-inline: 0.75rem;
        }

        .card {
          border-radius: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button[type="submit"] {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
          scroll-behavior: auto !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .option,
        button[type="submit"] {
          forced-color-adjust: auto;
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .eyebrow {
          border: 1px solid CanvasText;
        }

        .option:has(input:focus-visible),
        button[type="submit"]:focus-visible,
        a.skip-link:focus {
          outline: 2px solid Highlight;
          outline-offset: 2px;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <main id="maincontent" tabindex="-1">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Notification settings</h1>
        <p class="intro">Choose the channel you want us to use when we send you updates.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
              <p class="help-text" id="notification-help">Pick one option. You can change this later.</p>

              <div class="options">
                <label class="option" for="notification-email">
                  <input id="notification-email" name="notification-preference" type="radio" value="email" required />
                  <span class="option-text">
                    <span class="option-title">Email</span>
                    <span class="option-copy">Best for longer updates and summaries.</span>
                  </span>
                </label>

                <label class="option" for="notification-sms">
                  <input id="notification-sms" name="notification-preference" type="radio" value="sms" required />
                  <span class="option-text">
                    <span class="option-title">SMS</span>
                    <span class="option-copy">Useful for time-sensitive alerts.</span>
                  </span>
                </label>

                <label class="option" for="notification-push">
                  <input id="notification-push" name="notification-preference" type="radio" value="push" required />
                  <span class="option-text">
                    <span class="option-title">Push Notifications</span>
                    <span class="option-copy">Great for instant updates in the app.</span>
                  </span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Save preferences</button>
          </div>

          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = form.querySelector('input[name="notification-preference"]:checked');
        if (!selected) {
          status.textContent = "Error: Choose one notification method before saving.";
          return;
        }

        status.textContent = `Saved: ${selected.nextElementSibling.querySelector(".option-title").textContent}.`;
      });
    </script>
  </body>
</html>
