                <label class="option" for="notification-push">
                  <input id="notification-push" name="notification-preference" type="radio" value="push" required />
                  <span class="option-text">
                    <span class="option-title">Push Notifications</span>
                    <span class="option-copy">Great for instant updates in the app.</span>
                  </span>
