          status.textContent = "Error: Choose one notification method before saving.";
          form.querySelector('input[name="notification-preference"]').focus();
          return;
        }

        const label = selected.closest("label");
        const name = label ? label.querySelector(".option-title").textContent : "your choice";
        status.textContent = `Saved: ${name}.`;
      });
